package com.fitmate.backend.matechat.application
import com.fitmate.backend.common.error.*
import com.fitmate.backend.common.api.CursorPageResponse
import com.fitmate.backend.common.persistence.UuidBinaryConverter
import com.fitmate.backend.auth.domain.AccountStatus
import com.fitmate.backend.auth.repository.UserRepository
import com.fitmate.backend.mate.domain.*
import com.fitmate.backend.mate.repository.*
import com.fitmate.backend.matechat.api.*
import com.fitmate.backend.matechat.domain.*
import com.fitmate.backend.matechat.repository.*
import com.fitmate.backend.notification.application.NotificationWriter
import com.fitmate.backend.member.repository.UserProfileRepository
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import org.springframework.data.domain.PageRequest
import java.util.UUID
@Service class MateChatService(private val posts:MatePostRepository,private val applications:MateParticipationRepository,private val rooms:MateChatRoomRepository,private val messages:MateChatMessageRepository,private val notifications:NotificationWriter,private val users:UserRepository,private val profiles:UserProfileRepository){
 @Transactional fun room(user:UUID,postId:UUID):Pair<MateRoomResponse,Boolean>{val p=posts.findLocked(postId)?:notFound();if(p.authorId==user)throw ApiException(ApiErrorCode.FORBIDDEN_RESOURCE);rooms.findByPostIdAndInquirerId(requireNotNull(p.id),user)?.let{return room(it,user) to false};if(p.status!=MatePostStatus.RECRUITING||p.scheduledStartAt<=java.time.Instant.now())throw ApiException(ApiErrorCode.MATE_POST_NOT_RECRUITING);val r=rooms.save(MateChatRoom(UUID.randomUUID(),p,user));return room(r,user) to true}
 @Transactional(readOnly=true) fun get(user:UUID,id:UUID)=room(access(user,id),user)
 @Transactional(readOnly=true) fun rooms(user:UUID,cursor:String?,size:Int): CursorPageResponse<MateRoomResponse> {val boundary=decodeCursor(cursor);val limit=size.coerceIn(1,100);val selected=rooms.findPageForUser(user,boundary?.first,boundary?.second,PageRequest.of(0,limit+1));val hasNext=selected.size>limit;val values=selected.take(limit);return CursorPageResponse(values.map{room(it,user)},if(hasNext)encodeCursor(values.last().updatedAt,requireNotNull(values.last().id))else null,hasNext)}
 @Transactional(readOnly=true) fun messages(user:UUID,id:UUID,before:Long?,after:Long?,size:Int):List<MateMessageResponse>{if(before!=null&&after!=null)throw ApiException(ApiErrorCode.VALIDATION_ERROR);val r=access(user,id);val page=PageRequest.of(0,size.coerceIn(1,100));val rows=when{after!=null->messages.findAllByRoomIdAndSequenceNoGreaterThanOrderBySequenceNoAsc(requireNotNull(r.id),after,page);before!=null->messages.findAllByRoomIdAndSequenceNoLessThanOrderBySequenceNoDesc(requireNotNull(r.id),before,page).reversed();else->messages.findAllByRoomIdOrderBySequenceNoAsc(requireNotNull(r.id),page)};return rows.map(::message)}
 @Transactional fun send(user:UUID,id:UUID,request:SendMateMessageRequest):Pair<MateMessageResponse,Boolean>{val probe=rooms.findById(id).orElseThrow{notFound()};val p=posts.findLocked(requireNotNull(probe.post?.id))?:notFound();val room=rooms.findLocked(id)?:notFound();access(room,user);messages.findByRoomIdAndSenderIdAndClientMessageId(requireNotNull(room.id),user,request.clientMessageId)?.let{if(it.body!=request.body.trim())throw ApiException(ApiErrorCode.IDEMPOTENCY_KEY_CONFLICT);return message(it) to false};if(!writable(p,room))throw ApiException(ApiErrorCode.MATE_CHAT_READ_ONLY);val m=messages.save(MateChatMessage(UUID.randomUUID(),room,user,request.clientMessageId,room.lastMessageSequence+1,request.body.trim()));room.lastMessageSequence=m.sequenceNo;val receiver=if(p.authorId==user)room.inquirerId else p.authorId;notifications.mate(requireNotNull(receiver),user,if(m.sequenceNo==1L)"MATE_INQUIRY_RECEIVED" else "MATE_MESSAGE_RECEIVED",if(m.sequenceNo==1L)"mate_inquiry:${requireNotNull(room.id)}" else "mate_message:${requireNotNull(m.id)}","{\"postId\":\"${requireNotNull(p.id)}\",\"roomId\":\"${requireNotNull(room.id)}\",\"messageId\":\"${requireNotNull(m.id)}\"}");return message(m) to true}
 @Transactional fun read(user:UUID,id:UUID,messageId:UUID):MateRoomResponse{val r=rooms.findLocked(id)?:notFound();access(r,user);val m=messages.findByIdAndRoomId(messageId,requireNotNull(r.id))?:notFound();if(r.post?.authorId==user)r.hostLastReadSequence=maxOf(r.hostLastReadSequence,m.sequenceNo) else r.inquirerLastReadSequence=maxOf(r.inquirerLastReadSequence,m.sequenceNo);return room(r,user)}
 private fun access(u:UUID,id:UUID)=rooms.findById(id).orElseThrow{notFound()}.also{access(it,u)};private fun access(r:MateChatRoom,u:UUID){if(r.inquirerId!=u&&r.post?.authorId!=u)notFound()};private fun writable(p:MatePost,r:MateChatRoom):Boolean=readOnlyReason(p,r)==null;private fun readOnlyReason(p:MatePost,r:MateChatRoom):String?{if(!active(requireNotNull(p.authorId))||!active(requireNotNull(r.inquirerId)))return "INACTIVE_ACCOUNT";if(p.status==MatePostStatus.CANCELED)return "POST_CANCELED";val a=applications.findByPostIdAndUserId(requireNotNull(p.id),requireNotNull(r.inquirerId));if(p.status==MatePostStatus.CLOSED)return if(a?.status==MateParticipationStatus.ACCEPTED)null else "POST_CLOSED";return when(a?.status){MateParticipationStatus.REJECTED->"APPLICATION_REJECTED";MateParticipationStatus.CANCELED->"APPLICATION_CANCELED";MateParticipationStatus.WITHDRAWN->"APPLICATION_WITHDRAWN";else->null}};private fun active(id:UUID)=users.findById(id).map{it.accountStatus==AccountStatus.ACTIVE}.orElse(false);private fun summary(id:UUID)=MateUserSummary(id,profiles.findById(id).orElse(null)?.nickname);private fun room(r:MateChatRoom,u:UUID):MateRoomResponse{val p=requireNotNull(r.post);val reason=readOnlyReason(p,r);val read=if(p.authorId==u)r.hostLastReadSequence else r.inquirerLastReadSequence;val last=messages.findFirstByRoomIdOrderBySequenceNoDesc(requireNotNull(r.id))?.let(::message);return MateRoomResponse(requireNotNull(r.id),requireNotNull(p.id),summary(requireNotNull(p.authorId)),summary(requireNotNull(r.inquirerId)),if(reason==null)"ACTIVE" else "READ_ONLY",reason==null,reason,r.lastMessageSequence,r.hostLastReadSequence,r.inquirerLastReadSequence,read,r.lastMessageSequence-read,last)};private fun message(m:MateChatMessage)=MateMessageResponse(requireNotNull(m.id),requireNotNull(m.room?.id),requireNotNull(m.senderId),requireNotNull(m.clientMessageId),m.sequenceNo,m.body,"SENT",m.createdAt);private fun decodeCursor(value:String?):Pair<java.time.Instant,UUID>?=value?.let{runCatching{String(java.util.Base64.getUrlDecoder().decode(it)).split('|').let{parts->java.time.Instant.ofEpochMilli(parts[0].toLong()) to UUID.fromString(parts[1])}}.getOrElse{throw ApiException(ApiErrorCode.VALIDATION_ERROR,"cursor가 올바르지 않습니다.")}};private fun encodeCursor(at:java.time.Instant,id:UUID)=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString("${at.toEpochMilli()}|$id".toByteArray());private fun notFound():Nothing=throw ApiException(ApiErrorCode.RESOURCE_NOT_FOUND)
}
